begin;
select no_plan();
insert into auth.users(id) values ('00000000-0000-0000-0000-00000000a701'),('00000000-0000-0000-0000-00000000a702'),('00000000-0000-0000-0000-00000000a703'),('00000000-0000-0000-0000-00000000a704');
